contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take receiver and amount as inputs. We will call sendTo and observe whether it reverts,
    // and we will reason about the receiver's balance. To observe a balance increase we may use
    // this contract as receiver (so funds come to address(this)), or some other address; since
    // we cannot create new addresses, we check both the case receiver == address(this) and the general
    // case by observing address(c).balance and address(this).balance.
    function run(address receiver, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // Record balances before the call
        uint beforeC = address(c).balance;
        uint beforeReceiver = (receiver == address(this)) ? address(this).balance : address(receiver).balance;

        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;
        uint afterReceiver = (receiver == address(this)) ? address(this).balance : address(receiver).balance;

        // General rule:
        // - If the call did not revert and msg.sender was owner (the test contract is owner), then
        //   C's balance decreased by amount and the receiver's balance increased by amount.
        // - If the call reverted, receiver's balance did not change.
        // We cannot directly read owner, but the deployed owner is the deployer of c (the test contract),
        // so calls from here are from owner. Thus when not reverted, receiver gained amount.
        // Expressed as a single assert over observed balances and the revert flag:
        assert(
            reverted
            ? (afterReceiver == beforeReceiver)
            : (afterReceiver == beforeReceiver + amount)
        );
    }

    receive() external payable { }
}

